head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf93000";
scwin.std_cd_apct_tp_cd = null;
scwin.reg_button = null;
scwin.upd_batScdaplExcelFiles = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — stdCdApctTpCdList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.std_cd_apct_tp_cd = $c.util.getComponent('std_cd_apct_tp_cd');
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.upd_batScdaplExcelFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_batScdaplExcelFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_batScdaplExcelFiles"]');
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf93000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(elw vs elwfee) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name upd_batScdaplExcelFiles_onchange
 * @description upd_batScdaplExcelFiles 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.upd_batScdaplExcelFiles_onchange = function(e){
    try {
        fn_getFileNm1()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_getFileNm1 — as-is 공통(폼 전역 의존) — 반입 보류

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf93000.upd_batScdaplExcelFiles_onchange' }); }
};

/**
 * @method
 * @name rd_stdCdApctTpCd_onclick
 * @description rd_stdCdApctTpCd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_stdCdApctTpCd_onclick = function(e){
    try {
        scwin.setInsurInfo()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf93000.rd_stdCdApctTpCd_onclick' }); }
};

/**
 * @method
 * @name ipt_apctNm_onblur
 * @description ipt_apctNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_apctNm_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.chk_chrg_nm(selfVar, 20, '신청인 이름');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf93000.ipt_apctNm_onblur' }); }
};

/**
 * @method
 * @name ipt_encrypApctEmail1_onkeydown
 * @description ipt_encrypApctEmail1 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypApctEmail1_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf93000.ipt_encrypApctEmail1_onkeydown' }); }
};

/**
 * @method
 * @name ipt_encrypApctEmail2_onkeydown
 * @description ipt_encrypApctEmail2 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypApctEmail2_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf93000.ipt_encrypApctEmail2_onkeydown' }); }
};

/**
 * @method
 * @name btn_SendForm_onclick
 * @description btn_SendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_SendForm_onclick = async function(e){
    try {
        await scwin.Send_form()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf93000.btn_SendForm_onclick' }); }
};

/**
 * @method
 * @name btn_CancelForm_onclick
 * @description btn_CancelForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_CancelForm_onclick = function(e){
    try {
        scwin.Cancel_form()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf93000.btn_CancelForm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Send_form
 * @description Send form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Send_form = async function () {
    const sbmOptions = {
        id: "tx_Send_form",
        method: "post",
        action: "/fee/elwfee.do?method=elwBatchGrntFeeInfoView",
        ref: "dma_SendFormReq",
        target: "dlt_stdCdApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnRegSave
 * @description fn Reg Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnRegSave = async function () {
    const sbmOptions = {
        id: "tx_fnRegSave",
        method: "post",
        action: "/stdcd/elw.do?method=elwBatchScdaplExcelUpload",
        ref: "dma_fnRegSaveReq",
        target: "dlt_stdCdApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name Send_form
 * @description Send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Send_form = async function () {
    if (!await scwin.dataValidation()) {
        return;
    }
    $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
    let apct_tel_no = $c.util.getComponent('ipt_apctTelNo1').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo2').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo3').getValue(); if (apct_tel_no == null) { apct_tel_no = ''; }
    let apct_fax_no = $c.util.getComponent('ipt_apctFaxNo1').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo2').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo3').getValue(); if (apct_fax_no == null) { apct_fax_no = ''; }
    let apct_hp_no = $c.util.getComponent('ipt_apctHpNo1').getValue() + "-" + $c.util.getComponent('ipt_apctHpNo2').getValue() + "-" + $c.util.getComponent('ipt_apctHpNo3').getValue(); if (apct_hp_no == null) { apct_hp_no = ''; }
    let encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue(); if (encryp_apct_email == null) { encryp_apct_email = ''; }
    if (apct_fax_no === "--") {
        apct_fax_no = "";
    }
    $c.util.getComponent('ipt_apctTelNo').setValue(apct_tel_no);
    $c.util.getComponent('ipt_apctFaxNo').setValue(apct_fax_no);
    $c.util.getComponent('ipt_encrypCellphoneNo').setValue(apct_hp_no);
    $c.util.getComponent('ipt_encrypApctEmail').setValue(encryp_apct_email);
    if ($c.util.getComponent('ipt_stdCdGrntFeeApplYn').getValue() === 'Y') {
        const fm = (document.JLDINF93000 || { elements: [] });
        const width = 800;
        const height = 610;
        const mtWidth = document.body.clientWidth;
        const mtHeight = document.body.clientHeight;
        const scX = 0;
        const scY = 0;
        const popX = scX + (mtWidth - width) / 2;
        const popY = scY + (mtHeight - height) / 2;
        let _previewWindow;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/fee/elwfee.do?ipt_method=elwBatchGrntFeeInfoView", unresolved: "nav:" + "/fee/elwfee.do?ipt_method=elwBatchGrntFeeInfoView" }; })();
        fm.action = '/fee/elwfee.do?method=elwBatchGrntFeeInfoView';

    } else {
        await scwin.fnRegSave();
    }
};

/**
 * @method
 * @name fnRegSave
 * @description fn Reg Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnRegSave = async function () {

    const check_svc = $c.util.getComponent("dma_SendFormReq").get("checkSvc");
    scwin.reg_button.setStyle("display", "none");
    const sHost = location.hostname;
    await scwin.tx_fnRegSave();
};

/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_batScdaplExcelFilesNm').getValue()) === 0) {
        await $c.win.alert("일괄신청할 엑셀파일을 선택하세요.");
        $('#attach_file_nm6').focus();
        return false;
    }
    if ($("td#std_cd_apct_tp_cd input:checked").val() === "" || $("td#std_cd_apct_tp_cd input:checked").val() == null) {
        await $c.win.alert("신청인 소속구분을 선택하세요");
        scwin.std_cd_apct_tp_cd.focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) === 0) {
        await $c.win.alert("신청인 소속기관을 입력하세요");
        $c.util.getComponent("ipt_applComNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) > 60) {
        await $c.win.alert("신청인 소속기관을 한글 30자, 영문 60자이내로 입력하세요");
        $c.util.getComponent("ipt_applComNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) === 0) {
        await $c.win.alert("신청인 이름을  입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) > 20) {
        await $c.win.alert("신청인이름을 한글 10자, 영문 20자이내로 입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo1').getValue()) === 0) {
        await $c.win.alert("신청인 전화번호를  입력하세요");
        $c.util.getComponent("ipt_apctTelNo1").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo2').getValue()) === 0) {
        await $c.win.alert("신청인 전화번호를  입력하세요");
        $c.util.getComponent("ipt_apctTelNo2").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo3').getValue()) === 0) {
        await $c.win.alert("신청인 전화번호를  입력하세요");
        $c.util.getComponent("ipt_apctTelNo3").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo1').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo2').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo3').getValue()) > 0) {
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo1').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를  입력하세요");
            $c.util.getComponent("ipt_apctFaxNo1").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo2').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를  입력하세요");
            $c.util.getComponent("ipt_apctFaxNo2").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo3').getValue()) === 0) {
            await $c.win.alert("신청인 팩스번호를  입력하세요");
            $c.util.getComponent("ipt_apctFaxNo3").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctHpNo1').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_apctHpNo1").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctHpNo2').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_apctHpNo2").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctHpNo3').getValue()) === 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력하세요");
        $c.util.getComponent("ipt_apctHpNo3").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue()) === 0) {
        await $c.win.alert("신청인 이메일을 입력하세요");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail2').getValue()) === 0) {
        await $c.win.alert("신청인 이메일을 입력하세요");
        $c.util.getComponent("ipt_encrypApctEmail2").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue() + $c.util.getComponent('ipt_encrypApctEmail2').getValue()) > 40) {
        await $c.win.alert("신청인 이메일을 한글 20자, 영문 40자이내로 입력하세요");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return false;
    }
    let encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue(); if (encryp_apct_email == null) { encryp_apct_email = ''; }
    if (!$c.str.isEmail(encryp_apct_email)) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return false;
    }
    if (!checkLineFile()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name Cancel_form
 * @description Cancel form 처리
 * @returns {void}
 * @hidden N
 */
scwin.Cancel_form = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name setInsurInfo
 * @description set Insur Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInsurInfo = function () {
    if ($("td#std_cd_apct_tp_cd input:checked").val() === "1") {
        $c.util.getComponent('ipt_applComNm').setValue('' + dma_companyInfoVO.get("comNm") + '');
        $c.util.getComponent('ipt_apctNm').setValue('' + dma_companyInfoVO.get("chrgNm") + '');
        const apct_tel_no = '' + dma_companyInfoVO.get("chrgTelNo") + '';
        const apct_fax_no = '' + dma_companyInfoVO.get("chrgFaxNo") + '';
        const encryp_apct_email = '' + dma_companyInfoVO.get("chrgEmail") + '';
        const apct_hp_no = '' + dma_companyInfoVO.get("chrgCellphone") + '';
        if (apct_tel_no != null && apct_tel_no !== '') {
            const apct_tel_no_arr = apct_tel_no.split('-');
            const apct_tel_no_arr_size = apct_tel_no.match(/-/g).length;
            if (apct_tel_no_arr_size > 1) {
                if (apct_tel_no_arr[0] === "00") {
                    $c.util.getComponent('ipt_apctTelNo1').setValue('');
                } else {
                    $c.util.getComponent('ipt_apctTelNo1').setValue(apct_tel_no_arr[0]);
                }
                $c.util.getComponent('ipt_apctTelNo2').setValue(apct_tel_no_arr[1]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(apct_tel_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue('');
                $c.util.getComponent('ipt_apctTelNo2').setValue(apct_tel_no_arr[0]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(apct_tel_no_arr[1]);
            }
        }
        $c.util.getComponent('ipt_apctInnrNo').setValue('' + dma_companyInfoVO.get("chrgInnrNo") + '');
        if (apct_fax_no != null && apct_fax_no !== '') {
            const apct_fax_no_arr = apct_fax_no.split('-');
            const apct_fax_no_arr_size = apct_fax_no.match(/-/g).length;
            if (apct_fax_no_arr_size > 1) {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(apct_fax_no_arr[0]);
                $c.util.getComponent('ipt_apctFaxNo2').setValue(apct_fax_no_arr[1]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(apct_fax_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue('');
                $c.util.getComponent('ipt_apctFaxNo2').setValue(apct_fax_no_arr[0]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(apct_fax_no_arr[1]);
            }
        }
        if (apct_hp_no != null && apct_hp_no !== '') {
            const apct_hp_no_arr = apct_hp_no.split('-');
            const apct_hp_no_arr_size = apct_hp_no.match(/-/g).length;
            if (apct_hp_no_arr_size > 1) {
                $c.util.getComponent('ipt_apctHpNo1').setValue(apct_hp_no_arr[0]);
                $c.util.getComponent('ipt_apctHpNo2').setValue(apct_hp_no_arr[1]);
                $c.util.getComponent('ipt_apctHpNo3').setValue(apct_hp_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctHpNo1').setValue('');
                $c.util.getComponent('ipt_apctHpNo2').setValue(apct_hp_no_arr[0]);
                $c.util.getComponent('ipt_apctHpNo3').setValue(apct_hp_no_arr[1]);
            }
        }
        if (encryp_apct_email != null && encryp_apct_email !== '') {
            const encryp_apct_email_arr = encryp_apct_email.split('@');
            if (encryp_apct_email_arr.length < 2) {
                $c.util.getComponent('ipt_encrypApctEmail1').setValue(encryp_apct_email_arr[0]);
            } else {
                $c.util.getComponent('ipt_encrypApctEmail1').setValue(encryp_apct_email_arr[0]);
                $c.util.getComponent('ipt_encrypApctEmail2').setValue(encryp_apct_email_arr[1]);
            }
        }
    } else {
        $c.util.getComponent('ipt_applComNm').setValue("");
        $c.util.getComponent('ipt_apctNm').setValue("");
        $c.util.getComponent('ipt_encrypApctEmail1').setValue("");
        $c.util.getComponent('ipt_encrypApctEmail2').setValue("");
        $c.util.getComponent('ipt_apctTelNo1').setValue("");
        $c.util.getComponent('ipt_apctTelNo2').setValue("");
        $c.util.getComponent('ipt_apctTelNo3').setValue("");
        $c.util.getComponent('ipt_apctInnrNo').setValue("");
        $c.util.getComponent('ipt_apctFaxNo1').setValue("");
        $c.util.getComponent('ipt_apctFaxNo2').setValue("");
        $c.util.getComponent('ipt_apctFaxNo3').setValue("");
        $c.util.getComponent('ipt_apctHpNo1').setValue("");
        $c.util.getComponent('ipt_apctHpNo2').setValue("");
        $c.util.getComponent('ipt_apctHpNo3').setValue("");
    }
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
